    } else if (current !== null && typeof current === 'object') {
      if (!hasOwn(current, token)) throw new PointerError(`missing property: ${token} at ${at}`, at);
      current = current[token];
    } else {
      throw new PointerError(`cannot index into ${typeName(current)} at ${at}`, at);
    }
  }
  return current;
