function isProperPrefix(a, b) {
  return a.length < b.length && a.every((token, i) => token === b[i]);
}

/** Validate one operation's shape and decode its pointers. */
function prepare(operation) {
  if (operation === null || typeof operation !== 'object' || Array.isArray(operation)) {
    throw new PatchError('operation must be an object');
  }
  const op = operation.op;
  const known = ['add', 'remove', 'replace', 'move', 'copy', 'test'];
  if (typeof op !== 'string' || !known.includes(op)) throw new PatchError(`unknown operation: ${op}`);
  if (!hasOwn(operation, 'path')) throw new PatchError(`${op} requires a path`);
  const path = parsePointer(operation.path);
  const prepared = { op, path };
  if (op === 'add' || op === 'replace' || op === 'test') {
    if (!hasOwn(operation, 'value')) throw new PatchError(`${op} requires a value`);
    if (!isJsonData(operation.value)) throw new PatchError('value is not JSON data');
    prepared.value = operation.value;
  }
  if (op === 'move' || op === 'copy') {
    if (!hasOwn(operation, 'from')) throw new PatchError(`${op} requires a from`);
    prepared.from = parsePointer(operation.from);
  }
  return prepared;
}

/**
 * Apply a patch, leaving the input untouched whether or not it succeeds.
 *
 * @param {unknown} document JSON data to patch
 * @param {object[]} operations the patch
 * @returns {unknown} a new document with every operation applied
 */
export function applyPatch(document, operations) {
  if (!Array.isArray(operations)) throw new PatchError('patch must be an array');
  if (!isJsonData(document)) throw new PatchError('document is not JSON data');
  let root = deepCopy(document);
  for (let index = 0; index < operations.length; index += 1) {
    try {
      root = applyOne(root, operations[index]);
    } catch (error) {
      if (error instanceof PointerError) throw new PatchError(error.message, index, { cause: error });
      if (error instanceof PatchError) throw new PatchError(error.message, index, { cause: error.cause });
      throw error;
    }
  }
  return root;
}

/** Apply one operation to the working copy; returns the (possibly replaced) root. */
function applyOne(root, operation) {
  const { op, path, value, from } = prepare(operation);
  if (op === 'add') return addAt(root, path, deepCopy(value));
  if (op === 'remove') {
    if (path.length === 0) throw new PatchError('cannot remove the whole document');
    removeAt(root, path);
    return root;
  }
  if (op === 'replace') {
    if (path.length === 0) return deepCopy(value);
    resolveTokens(root, path);
    removeAt(root, path);
    return addAt(root, path, deepCopy(value));
  }
  if (op === 'test') {
    const actual = resolveTokens(root, path);
    if (!jsonEqual(actual, value)) throw new PatchError(`test failed at ${formatPointer(path)}`);
    return root;
  }
  if (op === 'copy') return addAt(root, path, deepCopy(resolveTokens(root, from)));
  // move
  resolveTokens(root, from);
  if (from.length === path.length && from.every((token, i) => token === path[i])) return root;
  if (isProperPrefix(from, path)) throw new PatchError('cannot move a value into its own child');
  const moved = removeAt(root, from);
  try {
    return addAt(root, path, moved);
  } catch (error) {
    addAt(root, from, moved);
    throw error;
  }
}
