  let current = document;
  const walked = prefix.slice();
  for (const token of tokens) {
    walked.push(token);
    const at = formatPointer(walked);
    if (Array.isArray(current)) {
      if (!isArrayIndex(token)) throw new PointerError(`invalid array index: ${token} at ${at}`, at);
