import {
  PointerError,
  formatPointer,
  hasOwn,
  isArrayIndex,
  parsePointer,
  resolveTokens,
  typeName,
} from './pointer.js';

/** Failure raised while applying a patch. */
export class PatchError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the operation that failed
   * @param {{ cause?: unknown }} [options] the underlying pointer failure, when there is one
   */
  constructor(message, index, options) {
    super(message, options);
    this.name = 'PatchError';
    this.index = index;
  }
}

/** @returns {boolean} whether the value is JSON data through and through */
function isJsonData(value) {
  if (value === null) return true;
  const type = typeof value;
  if (type === 'string' || type === 'boolean') return true;
  if (type === 'number') return Number.isFinite(value);
  if (type !== 'object') return false;
  if (Array.isArray(value)) return value.every(isJsonData);
  if (Object.getPrototypeOf(value) !== Object.prototype && Object.getPrototypeOf(value) !== null) return false;
  return Object.keys(value).every((key) => isJsonData(value[key]));
}

/** Set an own, enumerable property even when the key shadows `Object.prototype`. */
function setOwn(object, key, value) {
  Object.defineProperty(object, key, { value, writable: true, enumerable: true, configurable: true });
}

/** @returns {unknown} an independent copy of JSON data, keeping shadowing keys as own properties */
function deepCopy(value) {
  if (Array.isArray(value)) return value.map(deepCopy);
  if (value !== null && typeof value === 'object') {
    const copy = {};
    for (const key of Object.keys(value)) setOwn(copy, key, deepCopy(value[key]));
    return copy;
  }
  return value;
}

/** @returns {boolean} whether two pieces of JSON data are equal as JSON */
function jsonEqual(a, b) {
  if (a === b) return true;
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
    return a.every((item, i) => jsonEqual(item, b[i]));
  }
  if (a === null || b === null || typeof a !== 'object' || typeof b !== 'object') return false;
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;
  return keysA.every((key) => hasOwn(b, key) && jsonEqual(a[key], b[key]));
}

